//! Phantom Protocol — Post-quantum identity registration endpoint.
//!
//! Privacy Part 3: keys are generated by the client; only public keys are
//! accepted and stored here.
//!
//! POST /api/users/@me/phantom — Register a client-generated Phantom identity.
//! GET  /api/users/{id}/phantom  — Get a user's public Phantom identity.

use axum::{
    Json, Router,
    extract::{Extension, Path, State},
    http::StatusCode,
    routing::{get, post},
};
use nexus_common::models::phantom::{ClientPhantomRegistration, PhantomIdentity};
use nexus_db::repository::phantom as phantom_repo;
use serde::Serialize;
use std::sync::Arc;
use uuid::Uuid;

use crate::{AppState, middleware::AuthContext};

/// Response returned after successful identity registration.
#[derive(Debug, Serialize)]
struct PhantomIdentityResponse {
    did: String,
    kem_public: String,
    signing_public: String,
    created_at: String,
}

/// GET /api/users/{id}/phantom — Get a user's public Phantom identity.
#[derive(Debug, Serialize)]
struct PhantomPublicResponse {
    has_phantom: bool,
    did: Option<String>,
    kem_public: Option<String>,
    signing_public: Option<String>,
}

/// Register a client-generated Phantom identity for the authenticated user.
///
/// The client generates ML-KEM-1024 + ML-DSA-87 key pairs locally and sends
/// only the public keys here. Private keys never leave the client device.
async fn register_phantom_identity(
    State(state): State<Arc<AppState>>,
    Extension(auth): Extension<AuthContext>,
    Json(body): Json<ClientPhantomRegistration>,
) -> Result<(StatusCode, Json<PhantomIdentityResponse>), StatusCode> {
    let user_id = auth.user_id;
    let pool = &state.db.pool;

    // Already registered? Return the existing identity.
    let existing = phantom_repo::get_identity(pool, user_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    if let Some(identity) = existing {
        return Ok((
            StatusCode::OK,
            Json(PhantomIdentityResponse {
                did: identity.did,
                kem_public: identity.kem_public,
                signing_public: identity.signing_public,
                created_at: identity.created_at.to_rfc3339(),
            }),
        ));
    }

    let username = sqlx::query_scalar::<_, String>("SELECT username FROM users WHERE id = $1::uuid")
        .bind(user_id.to_string())
        .fetch_one(pool)
        .await
        .map_err(|_| StatusCode::NOT_FOUND)?;

    let did = format!(
        "did:phantom:{}",
        &hex::encode(blake3::hash(username.as_bytes()).as_bytes())[..16]
    );

    let identity = PhantomIdentity {
        user_id,
        did,
        kem_public: body.kem_public,
        signing_public: body.signing_public,
        created_at: chrono::Utc::now(),
    };

    let stored = phantom_repo::insert_identity(pool, &identity)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let identity = match stored {
        Some(identity) => identity,
        None => phantom_repo::get_identity(pool, user_id)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .ok_or(StatusCode::INTERNAL_SERVER_ERROR)?,
    };

    Ok((
        StatusCode::CREATED,
        Json(PhantomIdentityResponse {
            did: identity.did,
            kem_public: identity.kem_public,
            signing_public: identity.signing_public,
            created_at: identity.created_at.to_rfc3339(),
        }),
    ))
}

/// Get a user's public Phantom identity.
async fn get_user_phantom(
    State(state): State<Arc<AppState>>,
    Path(user_id): Path<Uuid>,
) -> Result<Json<PhantomPublicResponse>, StatusCode> {
    let identity = phantom_repo::get_identity(&state.db.pool, user_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    match identity {
        Some(id) => Ok(Json(PhantomPublicResponse {
            has_phantom: true,
            did: Some(id.did),
            kem_public: Some(id.kem_public),
            signing_public: Some(id.signing_public),
        })),
        None => Ok(Json(PhantomPublicResponse {
            has_phantom: false,
            did: None,
            kem_public: None,
            signing_public: None,
        })),
    }
}

pub fn router() -> Router<Arc<AppState>> {
    Router::new()
        .route("/users/@me/phantom", post(register_phantom_identity))
        .route("/users/{user_id}/phantom", get(get_user_phantom))
}
